import React from 'react';

import BGU from '@components/BGU';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';

import { IRecipe } from '../../@types/recipes.types';
interface IRecipeListItemForSelectProps {
  recipe: IRecipe;
  meta?: Record<string, any>;
}

const RecipeListItemForSelect: React.FC<IRecipeListItemForSelectProps> = ({ recipe, meta }) => {
  return (
    <div className="d-flex align-items-center ms-n2 ny-n3">
      <PohAva
        src={recipe.photo}
        alt={recipe.name}
        className="me-2"
        title={JSON.stringify(meta, null, ' ')}
      />
      <strong title={recipe.promo}>{recipe.name}</strong>
      <small className="ms-2 text-muted">
        {meta?.usagesCount && (
          <PohBadge variant={BadgeVariant.Warning}>{meta.usagesCount}</PohBadge>
        )}
      </small>
      <BGU
        portion={round(recipe.amount, 0)}
        energy={round(recipe.energy, 0)}
        protein={round(recipe.protein, 0)}
        fat={round(recipe.fat, 0)}
        carbohydrates={round(recipe.carbs, 0)}
        unit="в порции"
        className="ms-auto"
      />
    </div>
  );
};

export default RecipeListItemForSelect;
