import { get, handleApiError, post } from '@helpers/httpClient';

import { mapHikingRecipe } from '../@mappers/hikingRecipe.mapper';
import { IHikingRecipeDTO } from '../@types/hiking.backendTypes';
import { IHikingRecipe } from '../@types/hiking.baseTypes';

export const getHikingRecipes = async (id_hiking: number): Promise<IHikingRecipe[]> => {
  const res = await get<IHikingRecipeDTO[]>('/ajax/hiking/menu/recipes.php', { id_hiking });
  return res.map(mapHikingRecipe);
};

export const addHikingRecipes = async (
  id_hiking: number,
  recipes_ids: number[],
): Promise<number[]> => {
  const res = await post('/ajax/hiking/menu/recipe_add.php', {
    id_recipe: recipes_ids,
    id_hiking: id_hiking,
  }).then<{ ids: string[] }>(handleApiError);
  return res.ids.map(Number);
};

export const removeRecipeFromHiking = async (
  id_hiking: number,
  id_recipe: number,
): Promise<void> => {
  const res = await post('/ajax/hiking/menu/recipe_del.php', { id_recipe, id_hiking });
  return handleApiError(res);
};
